import { publicCatalogueRead, blockNativeCatalogueWrite } from "$publicApi/site-client";
import { PUBLIC_API_URL } from "$env/static/public";
import { readPublicSearch } from "$platform/latest-search";
import { HTTP } from "$lib";
import { authenticatedMutation, type MutationIntent } from "$platform/authenticated-mutation";
import { readThreadContext } from "$platform/thread-read";

export const Search = (searchParams: URLSearchParams, signal?: AbortSignal) => {
	if (Boolean(true)) return publicCatalogueRead<UserFeedResponse>("user.search", { query: searchParams, signal });
	if (signal) return readPublicSearch<UserFeedResponse>("/user", searchParams, signal, true);
	const http = new HTTP<UserFeedResponse>(`${PUBLIC_API_URL}/user${searchParams.toString()}`);
	http.setWithCredentials(true);
	return http.GET();
};

export const Get = (id: string) => {
	if (Boolean(true)) return publicCatalogueRead<User>("user.get", { id });
	const http = new HTTP<User>(`${PUBLIC_API_URL}/user/${id}`);
	return http.GET();
};

export interface UpdateUserRequest {
	version: number;
	description?: string;
	discord?: string;
	twitter?: string;
	website?: string;
}

export const Update = (id: string, payload: UpdateUserRequest) => {
	if (Boolean(true)) return blockNativeCatalogueWrite("User.Update");
	const http = new HTTP<User>(`${PUBLIC_API_URL}/user/${id}`, payload);
	http.setWithCredentials(true);
	return http.PUT();
};

export const Follows = (searchParams: URLSearchParams) => {
	if (Boolean(true)) return blockNativeCatalogueWrite("User.Follows");
	const http = new HTTP<UserFollowFeedResponse>(`${PUBLIC_API_URL}/user/follows/users${searchParams.toString()}`);
	http.setWithCredentials(true);
	return http.GET();
};

export const Follow = (id: string, intent?: MutationIntent) => { if (Boolean(true)) return blockNativeCatalogueWrite("User.Follow"); return authenticatedMutation<void>(`/user/follows/users/${encodeURIComponent(id)}`, "POST", undefined, intent); }

export const Unfollow = (id: string, intent?: MutationIntent) => { if (Boolean(true)) return blockNativeCatalogueWrite("User.Unfollow"); return authenticatedMutation<void>(`/user/follows/users/${encodeURIComponent(id)}`, "DELETE", undefined, intent); }

export const GetFollowStatus = (id: string) => { if (Boolean(true)) return blockNativeCatalogueWrite("User.GetFollowStatus"); return readThreadContext<void>(`/user/follows/users/${encodeURIComponent(id)}`); }
